import subprocess

def get_output(args, inp):
    r = subprocess.run(['./executable']+args, input=inp, stdout=subprocess.PIPE)
    return r.stdout.decode('utf-8', errors='replace')

def show(s):
    # show spaces as '.', and show borders
    return s.replace(' ', '.').replace('│','|').replace('┊','!').replace('┌','+').replace('┐','+').replace('└','+').replace('┘','+').replace('─','-').replace('┬','+').replace('┴','+').replace('├','+').replace('┤','+')

# Test default border none with 2 panels vs 1 panel
inp = b"A"*32
for panels in [1,2,3]:
    out = get_output(["--color=never","--border=none","--panels",str(panels)], inp)
    first = out.splitlines()[0]
    print(f"panels {panels} len {len(first)} raw {repr(first)} show {show(first)}")

# Test with group-size
for gs in [1,2,4,8]:
    out = get_output(["--color=never","--border=none","--panels","2","--group-size",str(gs)], inp)
    first = out.splitlines()[0]
    print(f"gs {gs} len {len(first)} {repr(first)}")

# Test bases
for base in ["binary","octal","decimal","hexadecimal"]:
    out = get_output(["--color=never","--border=none","--panels","1","--base",base], inp[:8])
    first = out.splitlines()[0]
    print(f"base {base} len {len(first)} {repr(first)}")

# Test with no-characters / no-position
for opts in [[], ["--no-characters"], ["--no-position"], ["--no-position","--no-characters"]]:
    out = get_output(["--color=never","--border=none","--panels","1"]+opts, inp[:8])
    first = out.splitlines()[0]
    print(f"opts {opts} len {len(first)} {repr(first)}")

# Test unicode border
for panels in [1,2]:
    out = get_output(["--color=never","--border=unicode","--panels",str(panels)], inp[:8*panels])
    print(f"unicode panels {panels}")
    for line in out.splitlines()[:3]:
        print(f"  len {len(line)} {repr(line)} show {show(line)}")

# Test ascii border similar
for panels in [1,2]:
    out = get_output(["--color=never","--border=ascii","--panels",str(panels)], inp[:8*panels])
    print(f"ascii panels {panels}")
    for line in out.splitlines()[:3]:
        print(f"  len {len(line)} {repr(line)}")

