fn get_value(val_opt: Option<String>, args: &Vec<String>, i: &mut usize, n: usize, arg_name: &str) -> Result<String, String> {
    if let Some(v) = val_opt {
        Ok(v)
    } else {
        if *i + 1 >= n {
            return Err(format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", arg_name));
        }
        *i += 1;
        Ok(args[*i].clone())
    }
}

fn parse_byte_count(s: &str, block_size: u64, arg_name: &str, _allow_negative: bool) -> Result<u64, String> {
    if s.starts_with('-') {
        return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    negative offset specified, but only positive offsets (counts) are accepted in this context\n", arg_name, s));
    }
    parse_byte_count_inner(s, block_size, arg_name)
}

fn parse_byte_count_signed(s: &str, block_size: u64, arg_name: &str) -> Result<i64, String> {
    let is_negative = s.starts_with('-');
    let inner = if is_negative { &s[1..] } else { s };
    if inner.is_empty() {
        return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    no character data found, did you forget to write it?\n", arg_name, s));
    }
    let unsigned = parse_byte_count_inner(inner, block_size, arg_name)?;
    if is_negative {
        Ok(-(unsigned as i64))
    } else {
        Ok(unsigned as i64)
    }
}

fn parse_byte_count_inner(s: &str, block_size: u64, arg_name: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    no character data found, did you forget to write it?\n", arg_name, s));
    }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() {
            return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: cannot parse integer from empty string\n", arg_name, s));
        }
        for c in hex_part.chars() {
            if !c.is_ascii_hexdigit() {
                return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string\n", arg_name, s));
            }
        }
        match u64::from_str_radix(hex_part, 16) {
            Ok(v) => return Ok(v),
            Err(_) => return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string\n", arg_name, s)),
        }
    }
    let mut idx = 0;
    let bytes = s.as_bytes();
    while idx < bytes.len() && bytes[idx].is_ascii_digit() {
        idx+=1;
    }
    if idx == 0 {
        if s.to_lowercase().starts_with("block") {
            return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"block\" is a valid unit, but an integer should come before it\n", arg_name, s));
        }
        return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]\n", arg_name, s, s));
    }
    let num_str = &s[..idx];
    let unit_str = &s[idx..];
    let num: u64 = match num_str.parse() {
        Ok(v) => v,
        Err(_) => return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: invalid digit found in string\n", arg_name, s)),
    };
    if unit_str.is_empty() {
        return Ok(num);
    }
    let unit_lower = unit_str.to_lowercase();
    let multiplier: u64 = if unit_lower == "block" || unit_lower == "blocks" {
        block_size
    } else if unit_lower == "kb" { 1000 }
    else if unit_lower == "kib" { 1024 }
    else if unit_lower == "mb" { 1000*1000 }
    else if unit_lower == "mib" { 1024*1024 }
    else if unit_lower == "gb" { 1000*1000*1000 }
    else if unit_lower == "gib" { 1024*1024*1024 }
    else if unit_lower == "tb" { 1000*1000*1000*1000 }
    else if unit_lower == "tib" { 1024*1024*1024*1024 }
    else {
        return Err(format!("Error: failed to parse `{}` arg \"{}\" as byte count\n\nCaused by:\n    invalid unit \"{}\"\n", arg_name, s, unit_str));
    };
    match num.checked_mul(multiplier) {
        Some(v) => Ok(v),
        None => Ok(u64::MAX),
    }
}

fn parse_block_size(s: &str) -> Result<u64, String> {
    if s.starts_with('-') {
        return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s));
    }
    if s.to_lowercase().contains("block") {
        return Err(format!("Error: can not use 'block(s)' as a unit to specify block size\n"));
    }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() {
            return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s));
        }
        for c in hex_part.chars() { if !c.is_ascii_hexdigit() { return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s)); } }
        return match u64::from_str_radix(hex_part, 16) {
            Ok(v) => Ok(v),
            Err(_) => return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s)),
        };
    }
    if s.is_empty() { return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s)); }
    let mut idx = 0;
    let bytes = s.as_bytes();
    while idx < bytes.len() && bytes[idx].is_ascii_digit() { idx+=1; }
    if idx == 0 { return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s)); }
    let num_str = &s[..idx];
    let unit_str = &s[idx..];
    let num: u64 = match num_str.parse() { Ok(v)=>v, Err(_)=> return Err(format!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]\n", s)) };
    if unit_str.is_empty() { return Ok(num); }
    let unit_lower = unit_str.to_lowercase();
    let mult = if unit_lower=="kb"{1000} else if unit_lower=="kib"{1024} else if unit_lower=="mb"{1000*1000} else if unit_lower=="mib"{1024*1024} else if unit_lower=="gb"{1000*1000*1000} else if unit_lower=="gib"{1024*1024*1024} else if unit_lower=="tb"{1000*1000*1000*1000} else if unit_lower=="tib"{1024*1024*1024*1024} else { return Err(format!("Error: invalid unit \"{}\"\n", unit_str)); };
    Ok(num*mult)
}

