                        // We'll handle duplicate -e as error if already seen via -e alone. Need separate flag for e.
                        // Simplify: treat -e as setting endianness to little, but not marking seen_endianness for duplicate with --endianness
                        // However duplicate -e -e should error (we saw). So track separately.
                        static mut SEEN_E: bool = false;
                        // Use a separate seen flag via cfg? We'll use a local static? But function re-enters, need separate.
