        file_opt = Some(fname.clone());
        if let Some(skip_val) = cfg.skip {
            if skip_val >=0 {
                file.seek(SeekFrom::Start(skip_val as u64)).map_err(|_| format!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n"))?;
            } else {
                let abs = (-skip_val) as u64;
                if let Some(len)=file_len {
                    if abs > len { return Err(format!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n")); }
                    file.seek(SeekFrom::End(-(abs as i64))).map_err(|_| format!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n"))?;
                } else { return Err(format!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n")); }
            }
        }
        if let Some(len)=cfg.length {
            let mut lim = file.take(len);
            lim.read_to_end(&mut data).map_err(|e| e.to_string())?;
        } else {
            file.read_to_end(&mut data).map_err(|e| e.to_string())?;
        }
    } else {
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        if let Some(skip_val)=cfg.skip {
            if skip_val <0 {
                return Err(format!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n"));
            } else {
                let mut remaining = skip_val as u64;
                let mut buf=[0u8;8192];
                while remaining>0 {
                    let to_read = std::cmp::min(remaining, buf.len() as u64) as usize;
                    let n = handle.read(&mut buf[..to_read]).map_err(|e| e.to_string())?;
                    if n==0 { break; }
                    remaining-=n as u64;
                }
            }
        }
        if let Some(len)=cfg.length {
            let mut lim = handle.take(len);
            lim.read_to_end(&mut data).map_err(|e| e.to_string())?;
        } else {
            handle.read_to_end(&mut data).map_err(|e| e.to_string())?;
        }
    }
    Ok((data,file_opt))
}

