fn expected_len_calc(panels: usize, base: &str, group_size: u8, show_pos: bool, show_char: bool) -> usize {
    let per_byte = match base { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
    let groups_per_panel = 8 / group_size as usize;
    let panel_hex = groups_per_panel * (group_size as usize * per_byte) + (groups_per_panel -1);
    let total_hex = panels * panel_hex + (panels-1)*3;
    let offset_width = if show_pos {11} else {2};
    if show_char {
        let total_char = panels*8 + (panels-1)*1;
        offset_width + total_hex + 2 + total_char + 1
    } else {
        offset_width + total_hex + 2
    }
}

