fn determine_panels(cfg: &Config) -> Result<usize, String> {
    if let Some(p) = &cfg.panels {
        if p=="auto" {
            let term_width = if let Some(w)=cfg.terminal_width { w as usize } else {
                if let Some((w,_)) = terminal_size() { w as usize } else { 80 }
            };
            return Ok(calc_panels_for_width(term_width, cfg));
        } else {
            return Ok(p.parse::<usize>().unwrap());
        }
    }
    if let Some(w)=cfg.terminal_width {
        return Ok(calc_panels_for_width(w as usize, cfg));
    }
    let term_width = if let Some((w,_))=terminal_size() { w as usize } else { 80 };
    let max = calc_panels_for_width(term_width, cfg);
    if max >=2 { Ok(2) } else { Ok(1) }
}

fn terminal_size() -> Option<(u16,u16)> {
