fn calc_panels_for_width(width: usize, cfg: &Config) -> usize {
    let show_pos = if cfg.plain { false } else { !cfg.no_position };
    let show_char = {
        if cfg.plain { false } else {
            let args: Vec<String> = env::args().collect();
            let mut last: Option<bool>=None;
            for a in args.iter().skip(1) {
                if a=="--characters" || a=="-C" { last=Some(true); }
                if a=="--no-characters" { last=Some(false); }
            }
            last.unwrap_or(true)
        }
    };
    let mut best=1;
    for p in 1..=20 {
        let exp = expected_len_calc(p, &cfg.base, cfg.group_size, show_pos, show_char);
        let threshold = if p==1 {1} else { exp - p };
        if width >= threshold { best=p; } else { break; }
    }
    best
}

fn expected_len_calc(panels: usize, base: &str, group_size: u8, show_pos: bool, show_char: bool) -> usize {
    let per_byte = match base { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
    let groups_per_panel = 8 / group_size as usize;
    let panel_hex = groups_per_panel * (group_size as usize * per_byte) + (groups_per_panel -1);
    let total_hex = panels * panel_hex + (panels-1)*3;
    let offset_width = if show_pos {11} else {2};
    if show_char {
        let total_char = panels*8 + (panels-1)*1;
        offset_width + total_hex + 2 + total_char + 1
    } else {
        offset_width + total_hex + 2
    }
}

