                j+=1;
            }
            if j > i+1 {
                // found duplicates
                display_rows.push(Some(cur.clone()));
                display_rows.push(None); // star
                i=j;
            } else {
                display_rows.push(Some(cur.clone()));
                i+=1;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // Header for border
    if border!="none" && !data.is_empty() {
        let header = generate_header(panels, show_pos, show_char, get_hex_col_width(&cfg), border=="unicode");
