            writeln!(out, "{}", header).unwrap();
        } else {
            writeln!(out, "{}", header).unwrap();
        }
    }

    for entry in display_rows {
        if entry.is_none() {
            // star line
            let line = format_star_line(cfg, &border, show_pos, show_char, panels);
            writeln!(out, "{}", line).unwrap();
            continue;
        }
        let (off, chunk) = entry.unwrap();
        let line = format_data_line(off, &chunk, cfg, panels, bytes_per_row, use_color, &get_byte_color, &offset_color, &reset, show_pos, show_char, &character_table, &color_scheme);
        writeln!(out, "{}", line).unwrap();
    }
    // final offset line
    let final_offset = start_offset + data.len() as u64;
    let final_line = format_final_line(final_offset, cfg, panels, show_pos, show_char, &border, use_color, &offset_color, &reset);
    writeln!(out, "{}", final_line).unwrap();

    if border!="none" && !data.is_empty() {
        let footer = generate_footer(panels, show_pos, show_char, get_hex_col_width(cfg), border=="unicode");
        writeln!(out, "{}", footer).unwrap();
    }
    out.flush().unwrap();
    Ok(())
}

fn get_hex_col_width(cfg: &Config) -> usize {
    let per_byte = match cfg.base.as_str() { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
    let groups = 8 / cfg.group_size as usize;
    let panel_hex = groups * (cfg.group_size as usize * per_byte) + (groups -1);
    panel_hex + 2
}

fn byte_category(b: u8) -> u8 {
    if b==0 { 0 }
    else if b>=0x20 && b<=0x7e {
        if b==0x20 { 2 } else { 1 } // printable vs space? But 0x20 is whitespace, not printable for color? In default, 0x20 green, others cyan
        // Actually 0x20 should be category 2 (whitespace), not 1
    } else if b==0x09 || b==0x0a || b==0x0b || b==0x0c || b==0x0d || b==0x20 { 2 }
    else if b < 0x20 || b==0x7f { 3 }
    else if b>=0x80 { 4 }
    else { 3 }
}

fn parse_color_env(s: &str) -> Option<String> {
    let t = s.trim().to_lowercase();
    let map = [
        ("black", "\x1b[30m"),
        ("red", "\x1b[31m"),
        ("green", "\x1b[32m"),
        ("yellow", "\x1b[33m"),
        ("blue", "\x1b[34m"),
        ("magenta", "\x1b[35m"),
        ("cyan", "\x1b[36m"),
        ("white", "\x1b[37m"),
        ("bright black", "\x1b[90m"),
        ("bright red", "\x1b[91m"),
        ("bright green", "\x1b[92m"),
        ("bright yellow", "\x1b[93m"),
        ("bright blue", "\x1b[94m"),
        ("bright magenta", "\x1b[95m"),
        ("bright cyan", "\x1b[96m"),
        ("bright white", "\x1b[97m"),
    ];
    for (k,v) in &map {
        if t==*k { return Some(v.to_string()); }
    }
    if t.starts_with('#') && t.len()==7 {
        // hex color #rrggbb
        let r = u8::from_str_radix(&t[1..3],16).ok()?;
        let g = u8::from_str_radix(&t[3..5],16).ok()?;
        let b = u8::from_str_radix(&t[5..7],16).ok()?;
        return Some(format!("\x1b[38;2;{:03};{:03};{:03}m", r,g,b));
    }
    None
}

fn format_star_line(cfg: &Config, border: &str, show_pos: bool, show_char: bool, panels: usize) -> String {
    if border=="none" {
        // For border none, star line is " *                                                                              " with star at position after offset? Let's see observed: for border none, star line: ' *                                                                              \n' with leading space then star? Actually observed: ' *                                                                              \n' length? For panels 2, star line len same as data row but with " * " at start? Let's generate.
        // For border none, data row starts with " 00000000  hex...". Star line starts with " *" then spaces.
        // Observed for panels2: ' *                                                                              \n' (star at second char? Let's count: ' ' then '*' then many spaces)
        // For panels2, star line width should be same as data row length (80). Data row length 80. Star line observed length? For panels2, star line we saw length? Let's measure: ' *                                                                              \n' -> that is 1 space, *, then 78 spaces? Hard to know. We'll replicate as: " *" + " ".repeat(expected_len -2)
        let exp = expected_len_calc(panels, &cfg.base, cfg.group_size, show_pos, show_char);
        let mut s = String::new();
        s.push_str(" *");
        s.push_str(&" ".repeat(exp-2));
        return s;
    } else if border=="unicode" {
        // unicode star line: "│*       │                         ┊                         │        ┊        │"
        // Need to generate based on show_pos, show_char, panels, hex_col_width
        let per_byte = match cfg.base.as_str() { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
        let groups = 8 / cfg.group_size as usize;
        let panel_hex = groups * (cfg.group_size as usize * per_byte) + (groups -1);
        let hex_width = panel_hex + 2;
        let mut parts: Vec<String>=Vec::new();
        if show_pos {
            parts.push(format!("*       ")); // 8 width with * and spaces? Observed "*       " (star plus 7 spaces) inside position column
        }
        for _ in 0..panels {
            parts.push(" ".repeat(hex_width));
        }
        if show_char {
            for _ in 0..panels { parts.push("        ".to_string()); }
        }
        // Need separators: for unicode, between position and first hex: "│", between hex panels: "┊" (?) Actually data rows use "┊" between hex panels, and "│" between hex and char, and "┊" between char panels. For star line, observed: "│*       │                         ┊                         │        ┊        │"
        // So hex panels separated by "┊", char panels separated by "┊", hex-char boundary "│"
        // We'll need to construct with correct separators.

        // Build line: start "│", then position part, then "│", then hex parts joined by "┊", then "│", then char parts joined by "┊", then "│"

        let mut line = String::new();
        line.push('│');
        if show_pos {
            line.push_str(&parts[0]);
            line.push('│');
            // hex parts are next
            let hex_parts = &parts[1..1+panels];
            line.push_str(&hex_parts.join("┊"));
            line.push('│');
            if show_char {
                let char_parts = &parts[1+panels..];
                line.push_str(&char_parts.join("┊"));
                line.push('│');
            }
        } else {
            // no position: first part is hex
            let hex_parts = &parts[0..panels];
            line.push_str(&hex_parts.join("┊"));
            line.push('│');
            if show_char {
                let char_parts = &parts[panels..];
                line.push_str(&char_parts.join("┊"));
                line.push('│');
            }
        }
        return line;
    } else { // ascii
        let per_byte = match cfg.base.as_str() { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
        let groups = 8 / cfg.group_size as usize;
        let panel_hex = groups * (cfg.group_size as usize * per_byte) + (groups -1);
        let hex_width = panel_hex + 2;
        let mut parts: Vec<String>=Vec::new();
        if show_pos {
            parts.push(format!("*       "));
        }
        for _ in 0..panels { parts.push(" ".repeat(hex_width)); }
        if show_char { for _ in 0..panels { parts.push("        ".to_string()); } }
        let mut line=String::new();
        line.push('|');
        if show_pos {
            line.push_str(&parts[0]);
            line.push('|');
            let hex_parts=&parts[1..1+panels];
            line.push_str(&hex_parts.join("|"));
            line.push('|');
            if show_char {
                let char_parts=&parts[1+panels..];
                line.push_str(&char_parts.join("|"));
                line.push('|');
            }
        } else {
            let hex_parts=&parts[0..panels];
            line.push_str(&hex_parts.join("|"));
            line.push('|');
            if show_char {
                let char_parts=&parts[panels..];
                line.push_str(&char_parts.join("|"));
                line.push('|');
            }
        }
        return line;
    }
}

fn format_data_line(off: u64, chunk: &[u8], cfg: &Config, panels: usize, bytes_per_row: usize, use_color: bool, get_byte_color: &dyn Fn(u8, &str, bool)->String, offset_color: &str, reset: &str, show_pos: bool, show_char: bool, character_table: &str, color_scheme: &str) -> String {
    let border = cfg.border.as_str();
    let base = cfg.base.as_str();
    let group_size = cfg.group_size as usize;
    let endianness = cfg.endianness.as_str();

    // offset string
    let offset_str = if show_pos {
        if use_color {
            format!("{}{:08x}{}", offset_color, off, reset)
        } else {
            format!("{:08x}", off)
        }
    } else { "".to_string() };

    // Build hex panels
    let mut hex_panels: Vec<String> = Vec::new();
    let mut char_panels: Vec<String> = Vec::new();

    for p in 0..panels {
        let start = p*8;
        let end = std::cmp::min(start+8, chunk.len());
        let panel_bytes = if start < chunk.len() { &chunk[start..end] } else { &[] as &[u8] };
        // hex representation
        let mut hex_str = String::new();
        if panel_bytes.is_empty() {
            // empty panel: fill with spaces of panel width
            let per_byte = match base { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
            let groups = 8 / group_size;
            let panel_hex = groups * (group_size * per_byte) + (groups -1);
            hex_str = " ".repeat(panel_hex);
        } else {
            // Build groups
            let mut groups_vec: Vec<String> = Vec::new();
            for g in (0..8).step_by(group_size) {
                if g >= panel_bytes.len() {
                    // beyond panel data, need to pad? But panel_bytes length may be <8 for last row partial? For partial row, groups beyond data should be spaces?
                    // For simplicity, we will generate groups only for available bytes, but pad missing groups with spaces
                    // However for hex display, missing bytes should be spaces.
                    // Let's handle: if g >= panel_bytes.len(), then group is empty -> produce spaces of width group_size*per_byte
                    let per_byte = match base { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
                    let w = group_size * per_byte;
                    groups_vec.push(" ".repeat(w));
                } else {
                    let group_slice = &panel_bytes[g..std::cmp::min(g+group_size, panel_bytes.len())];
                    // Need to handle endianness: if little, reverse bytes within group before formatting
                    let mut display_bytes: Vec<u8> = group_slice.to_vec();
                    if endianness=="little" && display_bytes.len()==group_size {
                        display_bytes.reverse();
                    }
                    let mut grp_str = String::new();
                    for &b in &display_bytes {
                        let mut byte_rep = match base {
                            "binary" => format!("{:08b}", b),
                            "octal" => format!("{:03o}", b),
                            "decimal" => format!("{:03}", b),
                            _ => format!("{:02x}", b),
                        };
                        if use_color {
                            let col = get_byte_color(b, &color_scheme, use_color);
                            if !col.is_empty() {
                                byte_rep = format!("{}{}{}", col, byte_rep, reset);
                            }
                        }
                        grp_str.push_str(&byte_rep);
                    }
                    // If group incomplete (at end of partial row, where remaining bytes < group_size), need to handle? For last row with 10 bytes example, second panel has only 2 bytes. Group_size 1 would produce 2 bytes + 6 spaces padding? Actually for partial, we should produce hex for available bytes and spaces for missing positions.
                    // For group_size>1, partial group handling may leave incomplete group with fewer bytes -> should still display those bytes but without extra padding beyond missing bytes? For hex row, missing bytes are spaces.
                    // For incomplete group where group_slice len < group_size (at end of chunk but not full group), we have already handled by display_bytes len < group_size, we produce byte_reps for those bytes, but the group width should be group_size*per_byte, so we need to pad trailing missing bytes within group with spaces?
                    // If display_bytes len < group_size, the missing bytes within group should be spaces.
                    let per_byte = match base { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
                    let expected = group_size * per_byte;
                    if grp_str.len() < expected {
                        // need to account for ANSI codes not counting towards visible length; but we already wrapped each byte rep with color codes, so visible length is still expected, but string length includes ANSI.
                        // For padding, we need spaces without color.
                        let visible_len = display_bytes.len() * per_byte;
                        let pad = expected - visible_len;
                        grp_str.push_str(&" ".repeat(pad));
                    }
                    groups_vec.push(grp_str);
                }
            }
            // Join groups with single space
            // But need to handle case where panel has less than 8 bytes total: groups beyond data should be spaces, but we already handled g >= panel_bytes.len() case above for groups beyond.
            // For partial last panel where panel_bytes len <8 but we still have groups for remaining bytes, those groups are already spaces.
            hex_str = groups_vec.join(" ");
            // Now hex_str visible length should be panel_hex (23 for hex g1 etc). For full panel, it's that. For partial, it's also same width but with spaces for missing bytes.
        }
        hex_panels.push(hex_str);
        // char panel
        if show_char {
            let mut chars = String::new();
            for &b in panel_bytes {
                let ch = map_char(b, character_table);
                if use_color {
                    let col = get_byte_color(b, &color_scheme, use_color);
                    if !col.is_empty() {
                        chars.push_str(&format!("{}{}{}", col, ch, reset));
                    } else {
                        chars.push_str(&ch);
                    }
                } else {
                    chars.push_str(&ch);
                }
            }
            // pad to 8 chars with spaces (without color)
            if panel_bytes.len() < 8 {
                chars.push_str(&" ".repeat(8 - panel_bytes.len()));
            }
            char_panels.push(chars);
        }
    }

    // Now assemble line based on border
    if border=="none" {
        let mut line = String::new();
        if show_pos {
            line.push(' ');
            line.push_str(&offset_str);
            line.push_str("  ");
        } else {
            line.push_str("  ");
        }
        // hex panels joined by 3 spaces
        line.push_str(&hex_panels.join("   "));
        if show_char {
            line.push_str("  ");
            line.push_str(&char_panels.join(" "));
            line.push(' ');
