fn format_final_line(off: u64, cfg: &Config, panels: usize, show_pos: bool, show_char: bool, border: &str, use_color: bool, offset_color: &str, reset: &str) -> String {
    let offset_str = if show_pos {
        if use_color { format!("{}{:08x}{}", offset_color, off, reset) } else { format!("{:08x}", off) }
    } else { "".to_string() };
    let per_byte = match cfg.base.as_str() { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
    let groups = 8 / cfg.group_size as usize;
    let panel_hex = groups * (cfg.group_size as usize * per_byte) + (groups -1);
    let hex_width = panel_hex + 2;
    if border=="none" {
        let mut line = String::new();
        if show_pos {
            line.push(' ');
            line.push_str(&offset_str);
            // For final line with no hex data, after offset there are spaces to fill hex and char columns? Observed final line for none: ' 00000040                                                                       \n' offset plus many spaces (hex and char areas empty).
            // The final line's length should match data row length but with hex and char empty (spaces).
            // Compute expected len for panels: expected_len_calc(panels,...)
            // Then line should be offset (11 chars) + spaces to fill to expected len?
            // For border none, data row len 80 for panels2. Final line len also 80? Let's see observed final line for none panels2 with 64 bytes zeros: ' 00000040                                                                       \n' -> offset " 00000040 " (11) then 69 spaces? That's 80 total. So after offset, the rest is spaces.

            // We'll generate by creating expected length and filling.
            let exp = expected_len_calc(panels, &cfg.base, cfg.group_size, show_pos, show_char);
            // line currently has offset plus 2 spaces? Actually data row has offset " 00000000  " (11) then hex etc. For final line, after offset there is maybe 2 spaces before hex? In data row we had offset " 00000000  " then hex. For final, we have offset then spaces.
            // Simpler: generate final line as offset + spaces to reach exp length.
            // Our line currently is " " + offset + ""? We need to add "  " after offset as per data row? Data row after offset has "  " before hex. For final, after offset we should have spaces.
            // Let's just produce line as: " " + offset + "  " + spaces to fill remaining?
            // For border none final line we saw: ' 00000040' + many spaces (no hex/char). The offset is at start with leading space.
            // So line = format!(" {:08x}", off) plus spaces to fill to exp.

            // We'll construct final line as: if show_pos { format!(" {:08x}", off) + " ".repeat(exp - 9) } else { "  ".repeat? }

            // For now, simple: create string of length exp with offset at start.
            let mut s = format!(" {:08x}", off);
            // s len is 9 (space +8 hex). Need to pad to exp.
            // But data row's offset part is 11 (space +8 +2 spaces). For final line, after offset they still have 2 spaces before hex area, which are part of total length. So s should be 11: " " + offset + "  "
            s = format!(" {:08x}  ", off);
            // Now pad to exp with spaces
            if s.len() < exp {
                s.push_str(&" ".repeat(exp - s.len()));
            }
            return s;
        } else {
