            // For no_pos, data row starts with "  " then hex. Final line should be spaces? Probably just " ".repeat(exp)
            let exp = expected_len_calc(panels, &cfg.base, cfg.group_size, show_pos, show_char);
            return " ".repeat(exp);
        }
    } else if border=="unicode" {
        let mut line = String::new();
