            line.push('|');
            if show_char {
                let empty_char = "        ";
                let mut char_seg = String::new();
                char_seg.push_str(&empty_char);
                for _ in 1..panels {
                    char_seg.push('|');
                    char_seg.push_str(&empty_char);
                }
                line.push_str(&char_seg);
                line.push('|');
            }
            return line;
        } else {
            let per_byte = match cfg.base.as_str() { "binary"=>8, "octal"|"decimal"=>3, _=>2 };
            let groups = 8 / cfg.group_size as usize;
